CREATE TABLE emprunt_archive AS SELECT * FROM emprunt WHERE 1 = 0;

INSERT INTO emprunt_archive
  SELECT * FROM emprunt
  WHERE dateretoureffective IS NOT NULL AND dateretoureffective < ADD_MONTHS(SYSDATE, -24);
DELETE FROM emprunt
  WHERE dateretoureffective IS NOT NULL AND dateretoureffective < ADD_MONTHS(SYSDATE, -24);
COMMIT;
- Structure copiée avec WHERE 1 = 0 ; INSERT puis DELETE avec la même condition ; un seul COMMIT.

SET SERVEROUTPUT ON
ACCEPT p_nom    PROMPT 'Nom : '
ACCEPT p_prenom PROMPT 'Prenom : '
ACCEPT p_email  PROMPT 'Email : '
DECLARE
  v_nom    adherent.nom%TYPE    := '&p_nom';
  v_prenom adherent.prenom%TYPE := '&p_prenom';
  v_email  adherent.email%TYPE  := '&p_email';
BEGIN
  INSERT INTO adherent (idadherent, nom, prenom, email, datinscription)
  VALUES (seq_adherent.NEXTVAL, v_nom, v_prenom, v_email, TRUNC(SYSDATE));
  COMMIT;
  DBMS_OUTPUT.PUT_LINE('Adherent ' || v_nom || ' ' || v_prenom || ' ajoute');
END;
/
- ACCEPT/& pour la saisie, NEXTVAL pour l'identifiant, COMMIT après l'insertion.

CREATE OR REPLACE PROCEDURE supprimerlivre (p_id IN NUMBER) IS
  v_nb NUMBER;
BEGIN
  SELECT COUNT(*) INTO v_nb FROM livre WHERE idlivre = p_id;
  IF v_nb = 0 THEN
    RAISE_APPLICATION_ERROR(-20050, 'Livre inexistant');
  END IF;

  SELECT COUNT(*) INTO v_nb FROM emprunt
  WHERE idlivre = p_id AND dateretoureffective IS NULL;
  IF v_nb > 0 THEN
    RAISE_APPLICATION_ERROR(-20051, 'Livre actuellement emprunte');
  END IF;

  DELETE FROM livre WHERE idlivre = p_id;
END supprimerlivre;
/
- Deux contrôles successifs avec COUNT(*) (qui ne lève jamais NO_DATA_FOUND), puis suppression.
- Pas de COMMIT : l'appelant valide. (Les emprunts déjà rendus peuvent être bloqués par la clé étrangère : ORA-02292.)

ALTER TABLE adherent ADD (penalite NUMBER DEFAULT 0);

CREATE OR REPLACE PROCEDURE majpenalite (p_id IN NUMBER) IS
  v_jours NUMBER;
  v_pen   NUMBER;
BEGIN
  SELECT NVL(SUM(dateretoureffective - dateretourprevue), 0) INTO v_jours
  FROM emprunt
  WHERE idadherent = p_id
    AND dateretoureffective IS NOT NULL
    AND dateretoureffective > dateretourprevue;

  IF v_jours = 0 THEN v_pen := 0;
  ELSIF v_jours <= 10 THEN v_pen := 500;
  ELSIF v_jours <= 30 THEN v_pen := 1500;
  ELSE v_pen := 3000;
  END IF;

  UPDATE adherent SET penalite = v_pen WHERE idadherent = p_id;
  IF SQL%ROWCOUNT = 0 THEN
    RAISE_APPLICATION_ERROR(-20052, 'Adherent inconnu');
  END IF;
  COMMIT;
END majpenalite;
/
- NVL(SUM(...), 0) : sans retard, SUM vaut NULL.
- ELSIF du plus petit seuil au plus grand.
- Ici l'énoncé demande le COMMIT : on valide dans la procédure.
